BEGIN;
LOCK TABLE webhook_subscription,webhook_subscription_history,webhook_delivery_history IN ACCESS EXCLUSIVE MODE;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM webhook_subscription) OR EXISTS(SELECT 1 FROM webhook_delivery_history) THEN RAISE EXCEPTION 'Refusing to remove retained webhook subscription or delivery evidence' USING ERRCODE='55000';END IF;END $$;
REVOKE ALL ON FUNCTION refs_webhook_subscription_create_hash(uuid,uuid,text,text,text,text[],text,text,text),refs_webhook_subscription_transition_hash(uuid,uuid,uuid,text,bigint,text),refs_create_webhook_subscription(uuid,uuid,text,text,text,text[],text,text,text,text,text),refs_transition_webhook_subscription(uuid,uuid,uuid,text,bigint,text,text,text),refs_read_webhook_subscription(uuid,uuid,uuid),refs_read_webhook_delivery_history(uuid,uuid,uuid,integer,timestamptz,uuid) FROM refs_app;
DROP TRIGGER webhook_subscription_protect ON webhook_subscription;DROP TRIGGER webhook_subscription_history_append_only ON webhook_subscription_history;DROP TRIGGER webhook_delivery_history_append_only ON webhook_delivery_history;DROP FUNCTION refs_read_webhook_delivery_history(uuid,uuid,uuid,integer,timestamptz,uuid);DROP FUNCTION refs_read_webhook_subscription(uuid,uuid,uuid);DROP FUNCTION refs_transition_webhook_subscription(uuid,uuid,uuid,text,bigint,text,text,text);DROP FUNCTION refs_create_webhook_subscription(uuid,uuid,text,text,text,text[],text,text,text,text,text);DROP FUNCTION refs_webhook_subscription_payload(uuid,uuid,uuid);DROP FUNCTION refs_webhook_subscription_transition_hash(uuid,uuid,uuid,text,bigint,text);DROP FUNCTION refs_webhook_subscription_create_hash(uuid,uuid,text,text,text,text[],text,text,text);DROP FUNCTION refs_guard_webhook_subscription();DROP TABLE webhook_subscription_gate;DROP TABLE webhook_delivery_history;DROP TABLE webhook_subscription_history;DROP TABLE webhook_subscription;UPDATE permission_catalog SET active=false,effective_to=clock_timestamp(),version=version+1 WHERE permission_code LIKE 'INTEGRATION.WEBHOOK.%';DELETE FROM runtime_human_permission_authority WHERE permission_code LIKE 'INTEGRATION.WEBHOOK.%';COMMIT;
